mapper.select:
select
ap.id, ap.status,ap.store_code, ap.store_name, ap.truncation_date_time, ap.delivery_cycle, ap.goods_code, ap.goods_name, ap.distribution_spec,ap.distribution_spec_num, ap.goods_level,
ap.base_display_quantity, ap.average_daily_sales_quantity,ap.compute_order_quantity,ap.recommend_order_quantity,ap.store_order_quantity,ap.supplement_quantity,
ap.supplement_package_quantity,ap.remark,ap.biz_org_code, ap.creator, ap.create_time, ap.updater, ap.update_time, ap.is_delete,ss.business_qty
    from ord_dir_order_allocation_pool ap
INNER JOIN gc_standard_goods_info sg on sg.goods_code = ap.goods_code and  sg.is_delete = 0
INNER JOIN gc_org_goods_info g on g.goods_id = sg.id and g.biz_org_code = ap.biz_org_code and  g.is_delete = 0
LEFT JOIN inv_stock_store ss on ss.store_code = ap.store_code and ss.goods_code = ap.goods_code and ss.biz_org_code = ap.biz_org_code
where 1 = 1

    and ap.store_code = #{storeCode}


    and ap.store_code in

        #{item}



    and ap.store_name like concat('%',#{storeName},'%')


    and ap.goods_code = #{goodsCode}


    and ap.goods_name like concat('%',#{goodsName},'%')


    and g.org_sort in

        #{item}



    and ap.status = #{status}


    and ap.supplement_quantity ${operation} #{supplementQuantity}


    and ap.biz_org_code = #{bizOrgCode}

order by ap.truncation_date_time,ap.store_code,ap.supplement_quantity desc
